   colloFull:[{zh:'学术泰斗',py:'xuéshù tàidǒu',vn:'bậc thầy học thuật'},{zh:'一代泰斗',py:'yí dài tàidǒu',vn:'bậc thầy một thời'},{zh:'音乐界的泰斗',py:'yīnyuèjiè de tàidǒu',vn:'bậc thầy giới âm nhạc'},{zh:'古陶瓷鉴定的泰斗',py:'gǔ táocí jiàndìng de tàidǒu',vn:'bậc thầy giám định gốm sứ cổ'},{zh:'成为泰斗',py:'chéngwéi tàidǒu',vn:'trở thành bậc thầy'}],
